insert into public.learning_content
(content_id,faculty,subject,content_type,access_tier,display_order,content_data,is_published)
values
('bmlt-labqa-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',600,'{"question":"Quality control in a laboratory is primarily used to:","translation":"Laboratory QC को मुख्य उद्देश्य के हो?","options":["Monitor analytical performance","Recruit staff","Decorate the laboratory","Replace maintenance"],"correctIndex":0,"explanation":"QC monitors whether test processes remain reliable and within acceptable limits.","explanationNe":"QC ले परीक्षणको performance स्वीकार्य सीमाभित्र छ कि छैन निगरानी गर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',601,'{"question":"Quality assurance is best described as:","translation":"Quality assurance भन्नाले के बुझिन्छ?","options":["A planned system ensuring quality throughout the testing process","Only repeating failed tests","Only checking reagents","Only final report printing"],"correctIndex":0,"explanation":"QA covers pre-analytical, analytical and post-analytical activities.","explanationNe":"QA ले sample देखि report सम्मका सबै चरणमा quality सुनिश्चित गर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',602,'{"question":"The three phases of laboratory testing are:","translation":"Laboratory testing का तीन phase कुन हुन्?","options":["Pre-analytical, analytical, post-analytical","Morning, afternoon, night","Collection, billing, cleaning","Screening, surgery, recovery"],"correctIndex":0,"explanation":"Testing includes activities before, during and after analysis.","explanationNe":"Pre-analytical, analytical र post-analytical phase हुन्।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',603,'{"question":"A common pre-analytical error is:","translation":"Pre-analytical error को उदाहरण कुन हो?","options":["Incorrect patient identification","Correct calibration","Proper control result","Validated method"],"correctIndex":0,"explanation":"Misidentification can cause serious patient harm.","explanationNe":"गलत patient identification गम्भीर pre-analytical error हो।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',604,'{"question":"A specimen label should include at minimum:","translation":"Specimen label मा न्यूनतम के हुनुपर्छ?","options":["Patient identifiers and specimen details","Only ward name","Only collection time","Only test price"],"correctIndex":0,"explanation":"Correct identifiers and specimen information ensure traceability.","explanationNe":"Patient identifier र specimen सम्बन्धी विवरण हुनुपर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',605,'{"question":"A hemolyzed blood sample may interfere with:","translation":"Hemolyzed blood sample ले केमा असर गर्न सक्छ?","options":["Several chemistry analytes","Only patient name","All tests never","Microscope focus only"],"correctIndex":0,"explanation":"Hemolysis can alter or interfere with many laboratory measurements.","explanationNe":"Hemolysis ले धेरै chemistry analyte को result बिगार्न सक्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',606,'{"question":"An internal quality control sample is usually analyzed:","translation":"Internal QC sample कहिले चलाइन्छ?","options":["Alongside patient samples at defined intervals","Only once per year","Only after issuing reports","Never with patient samples"],"correctIndex":0,"explanation":"IQC monitors ongoing analytical performance during routine work.","explanationNe":"Routine testing सँग निर्धारित interval मा IQC चलाइन्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',607,'{"question":"A Levey-Jennings chart displays QC results against:","translation":"Levey-Jennings chart मा QC result केसँग देखाइन्छ?","options":["Mean and standard deviation limits over time","Patient age only","Reagent price","Staff attendance"],"correctIndex":0,"explanation":"The chart tracks control values relative to mean and SD.","explanationNe":"QC result mean र SD limit अनुसार समयसँग देखाइन्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',608,'{"question":"A 1-2s Westgard rule is commonly used as:","translation":"Westgard 1-2s rule सामान्यतः के हो?","options":["A warning rule","Automatic proof of error","A calibration standard","A specimen rejection label"],"correctIndex":0,"explanation":"A single control exceeding ±2 SD warns of possible analytical problems.","explanationNe":"एक control ±2 SD बाहिर जाँदा warning दिन्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-010','BMLT','BMLT NHPC Licensing','mcq','free',609,'{"question":"The 1-3s Westgard rule indicates:","translation":"Westgard 1-3s rule ले के जनाउँछ?","options":["A control result exceeds ±3 SD","Two controls are exactly equal","A patient result is normal","No QC is required"],"correctIndex":0,"explanation":"A control beyond ±3 SD is typically a rejection signal.","explanationNe":"Control ±3 SD बाहिर हुनु rejection signal हो।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',610,'{"question":"Calibration establishes the relationship between:","translation":"Calibration ले कुन सम्बन्ध स्थापित गर्छ?","options":["Instrument response and known reference values","Patient name and test code","QC chart and staff roster","Sample color and diagnosis"],"correctIndex":0,"explanation":"Calibration relates measurement response to known standards.","explanationNe":"Instrument response र known reference value बीच सम्बन्ध स्थापित गर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',611,'{"question":"A reference interval generally describes values found in:","translation":"Reference interval ले सामान्यतः के जनाउँछ?","options":["A defined reference population","Every patient universally","Only critically ill patients","Only controls with disease"],"correctIndex":0,"explanation":"Reference intervals are established for a specified population and method.","explanationNe":"निर्धारित reference population मा पाइने value को सीमा हो।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',612,'{"question":"A critical laboratory result should be:","translation":"Critical result आएमा के गर्नुपर्छ?","options":["Promptly communicated according to policy and documented","Held until routine mail","Changed to normal","Ignored if QC passed"],"correctIndex":0,"explanation":"Critical results require timely notification and documentation.","explanationNe":"Policy अनुसार तुरुन्त सूचना दिएर documentation गर्नुपर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-014','BMLT','BMLT NHPC Licensing','mcq','free',613,'{"question":"A standard operating procedure should be:","translation":"SOP कस्तो हुनुपर्छ?","options":["Approved, current and accessible to staff","Kept only in one person''s memory","Changed without review","Used without training"],"correctIndex":0,"explanation":"Controlled SOPs standardize work and reduce variation.","explanationNe":"Approved, updated र staff लाई उपलब्ध हुनुपर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-015','BMLT','BMLT NHPC Licensing','mcq','free',614,'{"question":"Laboratory records should be maintained to support:","translation":"Laboratory record किन राखिन्छ?","options":["Traceability and audit","Decoration","Avoiding QC","Removing accountability"],"correctIndex":0,"explanation":"Records allow results, processes and corrective actions to be traced.","explanationNe":"Traceability, audit र corrective action का लागि record राखिन्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-016','BMLT','BMLT NHPC Licensing','mcq','free',615,'{"question":"A corrective action is taken to:","translation":"Corrective action को उद्देश्य के हो?","options":["Address the cause of a detected nonconformity","Hide an error","Increase sample volume","Skip documentation"],"correctIndex":0,"explanation":"Corrective action addresses the cause to prevent recurrence.","explanationNe":"त्रुटिको कारण हटाएर दोहोरिन नदिनु corrective action हो।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-017','BMLT','BMLT NHPC Licensing','mcq','free',616,'{"question":"Preventive maintenance is performed to:","translation":"Preventive maintenance किन गरिन्छ?","options":["Reduce equipment failure and maintain performance","Wait until instrument breaks","Replace QC","Avoid calibration"],"correctIndex":0,"explanation":"Scheduled maintenance helps prevent breakdowns and maintain reliability.","explanationNe":"Instrument बिग्रन नदिन र performance कायम राख्न गरिन्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-018','BMLT','BMLT NHPC Licensing','mcq','free',617,'{"question":"A laboratory temperature log is used to:","translation":"Temperature log ले के निगरानी गर्छ?","options":["Monitor storage and operating conditions","Record patient diagnosis","Calculate antibody titre","Replace reagent expiry dates"],"correctIndex":0,"explanation":"Temperature monitoring helps ensure conditions remain within requirements.","explanationNe":"Storage र operating temperature सही छ कि छैन हेर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-019','BMLT','BMLT NHPC Licensing','mcq','free',618,'{"question":"Expired reagents should be:","translation":"Expired reagent लाई के गर्नुपर्छ?","options":["Removed from use and handled according to policy","Used if color looks normal","Mixed with new reagents","Relabelled with a new date"],"correctIndex":0,"explanation":"Expired reagents may not perform as validated and should not be used.","explanationNe":"Use बाट हटाएर laboratory policy अनुसार व्यवस्थापन गर्नुपर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-020','BMLT','BMLT NHPC Licensing','mcq','free',619,'{"question":"A safety data sheet provides information about:","translation":"Safety data sheet मा के जानकारी हुन्छ?","options":["Chemical hazards, handling and emergency measures","Patient test results","Staff salaries","Instrument calibration values"],"correctIndex":0,"explanation":"SDS describes hazards, safe handling, storage and response measures.","explanationNe":"Chemical hazard, सुरक्षित handling र emergency उपाय हुन्छन्।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-021','BMLT','BMLT NHPC Licensing','mcq','free',620,'{"question":"The most appropriate routine hand hygiene practice is:","translation":"Routine hand hygiene कहिले गर्नुपर्छ?","options":["Clean hands before and after relevant patient/specimen contact","Wear gloves instead of hand hygiene","Wash only at shift end","Use the same gloves for all samples"],"correctIndex":0,"explanation":"Hand hygiene remains essential even when gloves are used.","explanationNe":"Glove लगाए पनि specimen/patient contact अघि र पछि हात सफा गर्नुपर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-022','BMLT','BMLT NHPC Licensing','mcq','free',621,'{"question":"Used needles should be discarded into:","translation":"प्रयोग भएको needle कहाँ फाल्नुपर्छ?","options":["A puncture-resistant sharps container","Regular paper bin","Open sink","A pocket"],"correctIndex":0,"explanation":"Sharps containers reduce needlestick and injury risks.","explanationNe":"Puncture-resistant sharps container मा फाल्नुपर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-023','BMLT','BMLT NHPC Licensing','mcq','free',622,'{"question":"A biological spill should be managed by:","translation":"Biological spill कसरी व्यवस्थापन गर्नुपर्छ?","options":["Following approved spill procedure with appropriate PPE and disinfectant","Wiping with bare hands","Blowing it dry","Leaving it for the next shift"],"correctIndex":0,"explanation":"Spill response requires appropriate PPE, containment and validated disinfection.","explanationNe":"PPE लगाएर approved spill procedure र disinfectant प्रयोग गर्नुपर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-024','BMLT','BMLT NHPC Licensing','mcq','free',623,'{"question":"External quality assessment evaluates performance by:","translation":"External quality assessment ले कसरी performance जाँच्छ?","options":["Comparing results with an external provider or peer laboratories","Checking staff attendance","Only reviewing reagent labels","Testing no samples"],"correctIndex":0,"explanation":"EQA/PT provides an independent comparison of laboratory performance.","explanationNe":"External provider वा peer lab सँग result तुलना गर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mcq-025','BMLT','BMLT NHPC Licensing','mcq','free',624,'{"question":"A laboratory audit is intended to:","translation":"Laboratory audit को उद्देश्य के हो?","options":["Assess compliance with defined requirements","Guarantee no errors ever","Replace staff competency assessment","Avoid document review"],"correctIndex":0,"explanation":"Audits evaluate whether processes meet specified standards and requirements.","explanationNe":"Process ले निर्धारित requirement पालना गरेको छ कि छैन जाँच्नु हो।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-001','BMLT','BMLT NHPC Licensing','mock','free',700,'{"question":"A patient sample arrives without required identifiers. The best action is to:","translation":"आवश्यक identifier नभएको sample आएमा के गर्ने?","options":["Reject or resolve identification according to policy before testing","Guess the patient from the ward","Run it and label later","Use the previous patient''s details"],"correctIndex":0,"explanation":"Unidentified specimens must not be processed as if identity were certain.","explanationNe":"Policy अनुसार reject वा identity resolve नगरी test गर्नु हुँदैन।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-002','BMLT','BMLT NHPC Licensing','mock','free',701,'{"question":"QC results show a persistent shift above the mean. This may suggest:","translation":"QC mean भन्दा लगातार माथि shift भए के संकेत हुन सक्छ?","options":["A systematic change in the process","Random labeling only","No need to investigate","A normal patient trend"],"correctIndex":0,"explanation":"A sustained shift may indicate systematic error or a process change.","explanationNe":"लगातार shift ले systematic error वा process change संकेत गर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-003','BMLT','BMLT NHPC Licensing','mock','free',702,'{"question":"QC results fluctuate widely around the mean. This may indicate:","translation":"QC result mean वरिपरि धेरै फैलिएको छ भने के हुन सक्छ?","options":["Increased random error","Perfect precision","Only patient disease","A correct reference interval"],"correctIndex":0,"explanation":"Wide scatter suggests imprecision or random variation.","explanationNe":"धेरै scatter हुनु imprecision वा random error को संकेत हो।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-004','BMLT','BMLT NHPC Licensing','mock','free',703,'{"question":"After QC failure, patient results should generally be:","translation":"QC fail भएपछि patient result के गर्नुपर्छ?","options":["Held until the issue is investigated and acceptable QC is restored","Released automatically","Adjusted by guessing","Reported without comments"],"correctIndex":0,"explanation":"Patient results should not be released from an out-of-control analytical run.","explanationNe":"समस्या समाधान र QC स्वीकार्य नभएसम्म result रोक्नुपर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-005','BMLT','BMLT NHPC Licensing','mock','free',704,'{"question":"A delta check compares:","translation":"Delta check ले के तुलना गर्छ?","options":["Current patient result with a previous result","Two reagent expiry dates","Two staff signatures","QC with a thermometer"],"correctIndex":0,"explanation":"Delta checks help identify unexpected changes or possible specimen errors.","explanationNe":"हालको patient result लाई अघिल्लो result सँग तुलना गर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-006','BMLT','BMLT NHPC Licensing','mock','free',705,'{"question":"A proficiency testing sample should be handled:","translation":"Proficiency testing sample कसरी चलाउनुपर्छ?","options":["Like a routine patient sample, following the program rules","By sharing answers with other labs","By changing results to match expected values","Without documentation"],"correctIndex":0,"explanation":"PT should reflect routine practice and follow provider instructions.","explanationNe":"Routine patient sample जस्तै र program नियमअनुसार चलाउनुपर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-007','BMLT','BMLT NHPC Licensing','mock','free',706,'{"question":"A new reagent lot is introduced. Appropriate action may include:","translation":"नयाँ reagent lot आएमा के गर्नुपर्छ?","options":["Lot verification and QC according to procedure","Immediate use without checks","Deleting previous QC","Changing patient reference ranges arbitrarily"],"correctIndex":0,"explanation":"New lots should be checked to ensure acceptable performance before routine use.","explanationNe":"Routine प्रयोगअघि procedure अनुसार lot verification र QC गर्नुपर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-008','BMLT','BMLT NHPC Licensing','mock','free',707,'{"question":"A pipette delivers less volume than set. This mainly affects:","translation":"Pipette ले कम volume दिएमा मुख्य असर के हुन्छ?","options":["Accuracy of measured volume and test results","Patient identification","Sample collection site only","Report formatting"],"correctIndex":0,"explanation":"Incorrect pipetting volume can cause systematic measurement errors.","explanationNe":"गलत volume ले measurement र result मा error ल्याउँछ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-009','BMLT','BMLT NHPC Licensing','mock','free',708,'{"question":"A balance used for weighing should be checked with:","translation":"Weighing balance कसले check गर्नुपर्छ?","options":["Suitable calibrated weights","Patient serum only","A thermometer","A urine strip"],"correctIndex":0,"explanation":"Appropriate certified or calibrated weights verify balance performance.","explanationNe":"उपयुक्त calibrated weight प्रयोग गरेर जाँच गर्नुपर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-010','BMLT','BMLT NHPC Licensing','mock','free',709,'{"question":"The purpose of equipment maintenance records is to:","translation":"Equipment maintenance record किन राखिन्छ?","options":["Document service, checks and performance history","Replace all SOPs","Hide breakdowns","Record only purchase price"],"correctIndex":0,"explanation":"Maintenance records support traceability and troubleshooting.","explanationNe":"Service, check र performance history trace गर्न।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-011','BMLT','BMLT NHPC Licensing','mock','free',710,'{"question":"A specimen transport condition is unsuitable. The lab should:","translation":"Transport condition नमिलेमा के गर्नुपर्छ?","options":["Assess acceptability and request recollection if required","Ignore transport time","Always process without comment","Freeze every specimen"],"correctIndex":0,"explanation":"Transport conditions can affect specimen integrity and test validity.","explanationNe":"Acceptability जाँचेर आवश्यक भए recollection माग्नुपर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-012','BMLT','BMLT NHPC Licensing','mock','free',711,'{"question":"A nonconformity is:","translation":"Nonconformity भन्नाले के बुझिन्छ?","options":["Failure to meet a specified requirement","Any normal test result","A routine calibration","A positive control"],"correctIndex":0,"explanation":"Nonconformity means a requirement has not been fulfilled.","explanationNe":"निर्धारित requirement पूरा नभएको अवस्था हो।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-013','BMLT','BMLT NHPC Licensing','mock','free',712,'{"question":"Root cause analysis aims to identify:","translation":"Root cause analysis ले के पत्ता लगाउँछ?","options":["Underlying cause of a problem","Only the person to blame","The fastest way to discard records","Patient''s blood group"],"correctIndex":0,"explanation":"Root cause analysis seeks causes that can be corrected to prevent recurrence.","explanationNe":"समस्या दोहोरिन नदिन underlying cause खोज्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-014','BMLT','BMLT NHPC Licensing','mock','free',713,'{"question":"A risk assessment in the laboratory is used to:","translation":"Laboratory risk assessment किन गरिन्छ?","options":["Identify hazards and plan controls","Replace all PPE","Guarantee zero risk","Determine patient diagnosis"],"correctIndex":0,"explanation":"Risk assessment identifies hazards, likelihood and controls.","explanationNe":"Hazard पहिचान गरी risk control योजना बनाउन।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-015','BMLT','BMLT NHPC Licensing','mock','free',714,'{"question":"The hierarchy of controls generally prioritizes:","translation":"Control hierarchy मा सामान्यतः कुन उपाय पहिले आउँछ?","options":["Elimination or substitution before relying only on PPE","PPE as the only control","Warnings over all other measures","No controls"],"correctIndex":0,"explanation":"Higher-level controls reduce hazards more reliably than PPE alone.","explanationNe":"Elimination वा substitution PPE मात्रमा निर्भर हुनुभन्दा माथि हुन्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-016','BMLT','BMLT NHPC Licensing','mock','free',715,'{"question":"A centrifuge tube should be balanced by:","translation":"Centrifuge tube कसरी balance गर्नुपर्छ?","options":["Opposing tubes with appropriate equal mass/volume","Placing all tubes on one side","Using a broken tube as counterweight","Running with lid open"],"correctIndex":0,"explanation":"Proper balancing reduces vibration and equipment damage.","explanationNe":"Opposite position मा उचित समान mass/volume राख्नुपर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-017','BMLT','BMLT NHPC Licensing','mock','free',716,'{"question":"A laboratory refrigerator temperature exceeds its permitted range. The first step is to:","translation":"Refrigerator temperature limit बाहिर गएमा पहिले के गर्ने?","options":["Follow the temperature excursion procedure and assess stored materials","Ignore the reading","Reset the thermometer record","Discard everything without assessment"],"correctIndex":0,"explanation":"Excursions require documentation and assessment of material stability.","explanationNe":"Excursion procedure अनुसार record र stored material को stability जाँच्ने।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-018','BMLT','BMLT NHPC Licensing','mock','free',717,'{"question":"A test method is changed significantly. The laboratory should consider:","translation":"Test method ठूलो परिवर्तन भएमा के गर्नुपर्छ?","options":["Verification or validation before routine reporting","No documentation","Changing only the test name","Skipping QC for a week"],"correctIndex":0,"explanation":"Method changes require appropriate performance evaluation before use.","explanationNe":"Routine reporting अघि verification वा validation गर्नुपर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-019','BMLT','BMLT NHPC Licensing','mock','free',718,'{"question":"A staff competency assessment may include:","translation":"Staff competency कसरी assess गर्न सकिन्छ?","options":["Observation, records review and practical assessment","Only years of service","Only a verbal promise","Patient diagnosis"],"correctIndex":0,"explanation":"Competency should be evaluated with documented evidence of performance.","explanationNe":"Observation, record review र practical assessment बाट।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-020','BMLT','BMLT NHPC Licensing','mock','free',719,'{"question":"A corrected laboratory report should:","translation":"Corrected report कस्तो हुनुपर्छ?","options":["Be traceable, clearly amended and communicated as required","Erase the original without trace","Be changed secretly","Never notify the requester"],"correctIndex":0,"explanation":"Amendments require an audit trail and appropriate notification.","explanationNe":"Traceable amendment र आवश्यक notification सहित हुनुपर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-021','BMLT','BMLT NHPC Licensing','mock','free',720,'{"question":"Confidential patient information should be:","translation":"Patient information कसरी सुरक्षित राख्नुपर्छ?","options":["Accessed and shared only by authorized persons for valid purposes","Posted publicly","Discussed in public areas","Included in unrelated messages"],"correctIndex":0,"explanation":"Confidentiality protects patient privacy and follows laboratory policy.","explanationNe":"Authorized व्यक्तिले आवश्यक प्रयोजनका लागि मात्र access/share गर्नुपर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-022','BMLT','BMLT NHPC Licensing','mock','free',721,'{"question":"A laboratory waste segregation system should separate:","translation":"Laboratory waste कसरी छुट्याउनुपर्छ?","options":["Waste according to hazard and local policy","All waste into one bag","Sharps with paper","Chemical waste into handwashing sink"],"correctIndex":0,"explanation":"Segregation supports safe handling and appropriate disposal.","explanationNe":"Hazard र local policy अनुसार waste अलग गर्नुपर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-023','BMLT','BMLT NHPC Licensing','mock','free',722,'{"question":"An autoclave''s sterilization cycle should be monitored using:","translation":"Autoclave sterilization cycle कसरी monitor गरिन्छ?","options":["Appropriate physical, chemical and biological indicators as required","Only the door color","Patient samples","A routine glucose control"],"correctIndex":0,"explanation":"Monitoring verifies that the cycle reached and maintained required conditions.","explanationNe":"आवश्यकता अनुसार physical, chemical र biological indicator प्रयोग हुन्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-024','BMLT','BMLT NHPC Licensing','mock','free',723,'{"question":"A document control system helps ensure staff use:","translation":"Document control ले के सुनिश्चित गर्छ?","options":["The current approved version","Any old photocopy","Drafts without approval","Documents with missing pages"],"correctIndex":0,"explanation":"Document control prevents unintended use of obsolete procedures.","explanationNe":"Staff ले current approved document प्रयोग गरून् भन्ने सुनिश्चित गर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true),
('bmlt-labqa-mock-025','BMLT','BMLT NHPC Licensing','mock','free',724,'{"question":"The best response to a laboratory incident is to:","translation":"Laboratory incident हुँदा उत्तम प्रतिक्रिया के हो?","options":["Ensure safety, report, document and investigate according to policy","Conceal it","Blame a colleague immediately","Continue without assessing risk"],"correctIndex":0,"explanation":"Incident management prioritizes safety, reporting and prevention of recurrence.","explanationNe":"Safety सुनिश्चित गरी report, document र policy अनुसार investigation गर्नुपर्छ।","topic":"Laboratory Management & Quality Assurance"}'::jsonb,true);
